if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pigId=(int)$_POST['pig_id'];$date=$_POST['mating_date'];$check=$pdo->prepare("SELECT COUNT(*) FROM sow_records WHERE pig_id=:pig AND status='pregnant'");$check->execute(['pig'=>$pigId]);if($check->fetchColumn()){ $error='This sow already has an active pregnancy record.';}else{ $statement=$pdo->prepare("INSERT INTO sow_records (pig_id,mating_date,expected_farrowing_date) VALUES (:pig,:mating_date,DATE_ADD(:expected_date, INTERVAL 114 DAY))");$statement->execute(['pig'=>$pigId,'mating_date'=>$date,'expected_date'=>$date]);flash('success','Mating recorded with a 114-day countdown.');redirect('sows/index.php');}}
require __DIR__ . '/../includes/header.php';
